sent, subs = [], {}  # 종목 → 보고 있는 탭 집합

def subscribe(tab, code):
    s = subs.setdefault(code, set())
    if not s:
        sent.append(f"SUB {code}")
    s.add(tab)

def unsubscribe(tab, code):
    s = subs.get(code)
    if s is None:
        return
    s.discard(tab)
    if not s:
        sent.append(f"UNSUB {code}")
        del subs[code]

def close_tab(tab):
    for code in list(subs):
        unsubscribe(tab, code)

subscribe("tab1", "005930"); subscribe("tab2", "005930"); subscribe("tab3", "005930")
subscribe("tab2", "AAPL")
close_tab("tab1"); close_tab("tab2")
print(" | ".join(sent))
print({c: len(s) for c, s in subs.items()})

# 서비스마다 따로 정한 카나리 비율 — 쿠키 번호(1~100)가 비율 이하면 새 버전
rollout = {"home": 60, "stock": 50, "trading": 10, "account": 30}

def import_map(cookie):
    return {svc: ("v2" if cookie <= pct else "v1") for svc, pct in rollout.items()}

for cookie in (7, 25, 88):
    print(cookie, import_map(cookie))

# 비율 10% → 50%: 10%일 때 새 버전을 본 사람은 50%에서도 새 버전(쿠키가 같아서)
at10 = {c for c in range(1, 101) if c <= 10}
at50 = {c for c in range(1, 101) if c <= 50}
print("10%에서 v2를 본 사람이 50%에서도 v2:", at10 <= at50)
